const visual = {
  prepare: function(input) {
    return [
      { kind: 'text', payload: '拔塞过程三阶段' },
      { kind: 'text', payload: 'u = x / h' },
      { kind: 'text', payload: 'u = 0' },
      { kind: 'text', payload: 'u = 1/2' },
      { kind: 'text', payload: 'u = 1' },
      { kind: 'text', payload: 'x = 0' },
      { kind: 'text', payload: 'x = h/2' },
      { kind: 'text', payload: 'x = h' },
      { kind: 'text', payload: '瓶口基准线' },
      { kind: 'text', payload: '位移按真实比例' }
    ];
  },
  render: function(input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = W * 0.05;
    var gap = W * 0.03;
    var panelW = (W - margin * 2 - gap * 2) / 3;
    var y0 = H * 0.56;
    var h = H * 0.20;
    var neckDepth = H * 0.23;
    var neckHalf = panelW * 0.16;
    var corkHalf = neckHalf * 0.82;
    var lip = panelW * 0.045;
    var yInitBottom = y0 + h;
    var centers = [];
    for (var i = 0; i < 3; i++) {
      centers.push(margin + panelW / 2 + i * (panelW + gap));
    }
    var paths = [];
    var children = [];
    var colorInk = '#26354A';
    var colorBottle = '#2F5D62';
    var colorCork = '#C89B62';
    var colorCorkStroke = '#6B4A2B';
    var colorGuide = '#9AA7B4';
    var colorArrow = '#1F5F8B';
    function addPath(id, commands, fill, stroke) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, fill: fill };
      if (stroke) node.stroke = stroke;
      children.push(node);
    }
    function rectCommands(x, y, w, hh) {
      return [['M', x, y], ['L', x + w, y], ['L', x + w, y + hh], ['L', x, y + hh], ['Z']];
    }
    function lineCommands(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }
    addPath('baseline', lineCommands(margin * 0.4, y0, W - margin * 0.4, y0), colorInk, { width: 2, dash: [7, 5] });
    addPath('init-bottom', lineCommands(margin * 0.4, yInitBottom, W - margin * 0.4, yInitBottom), colorGuide, { width: 1, dash: [4, 6] });
    var uVals = [0, 0.5, 1];
    for (var p = 0; p < 3; p++) {
      var cx = centers[p];
      var u = uVals[p];
      addPath('neck-l-' + p, lineCommands(cx - neckHalf, y0, cx - neckHalf, y0 + neckDepth), colorBottle, { width: 4, cap: 'round' });
      addPath('neck-r-' + p, lineCommands(cx + neckHalf, y0, cx + neckHalf, y0 + neckDepth), colorBottle, { width: 4, cap: 'round' });
      addPath('lip-l-' + p, lineCommands(cx - neckHalf - lip, y0, cx - neckHalf, y0), colorBottle, { width: 4, cap: 'round' });
      addPath('lip-r-' + p, lineCommands(cx + neckHalf, y0, cx + neckHalf + lip, y0), colorBottle, { width: 4, cap: 'round' });
      var top = y0 - u * h;
      var bottom = y0 + h * (1 - u);
      addPath('cork-' + p, rectCommands(cx - corkHalf, top, corkHalf * 2, h), colorCork, { width: 2, join: 'round' });
      if (u > 0) {
        var xDim = cx + neckHalf + panelW * 0.10;
        addPath('arrow-' + p, visualSdk.arrow(xDim, yInitBottom, xDim, bottom, {}), colorArrow, { width: 2, cap: 'round' });
        addPath('guide-' + p, lineCommands(cx + corkHalf, bottom, xDim, bottom), colorArrow, { width: 1, dash: [3, 3] });
      } else {
        var xDim0 = cx + neckHalf + panelW * 0.10;
        addPath('dot-' + p, visualSdk.circle(xDim0, yInitBottom, Math.max(2, W * 0.004)), colorArrow);
      }
    }
    function addLabel(i, x, y, hAlign, vAlign, color) {
      children.push({ type: 'label', contentId: metrics[i].contentId, anchor: { x: x, y: y }, hAlign: hAlign, vAlign: vAlign, color: color });
    }
    addLabel(0, W / 2, H * 0.075, 'center', 'middle', colorInk);
    addLabel(1, W / 2, H * 0.145, 'center', 'middle', colorInk);
    addLabel(8, margin * 0.4, y0 - H * 0.018, 'left', 'bottom', colorInk);
    addLabel(9, W / 2, H * 0.985, 'center', 'bottom', colorInk);
    for (var q = 0; q < 3; q++) {
      addLabel(2 + q, centers[q], y0 + neckDepth + H * 0.065, 'center', 'top', colorInk);
      addLabel(5 + q, centers[q], y0 + neckDepth + H * 0.115, 'center', 'top', colorInk);
    }
    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
